#include <iostream>
#include <string_view>

struct DATE {
    int ngay;
    int thang;
    int nam;
};

// Kiem tra nam nhuan
bool Nhuan(int nam) {
    return (nam % 4 == 0 && nam % 100 != 0) || (nam % 400 == 0);
}

// So ngay trong thang
int Ngayct(int thang, int nam) {
    switch (thang) {
        case 4: case 6: case 9: case 11: return 30;
        case 2: return Nhuan(nam) ? 29 : 28;
        default: return 31;
    }
}

// Tinh tong so ngay tu 1/1/nam 1
long Tongngay(DATE d) {
    long kq = 0;
    for (int i = 1; i < d.nam; ++i) {
        kq += 365 + (Nhuan(i) ? 1 : 0);
    }
    for (int i = 1; i < d.thang; ++i) {
        kq += Ngayct(i, d.nam);
    }
    kq += d.ngay;
    return kq;
}

// Khoang cach giua hai ngay
long Khoangcach(DATE d1, DATE d2) {
    return Tongngay(d1) - Tongngay(d2);
}

// Tinh thu dua tren moc 1/1/2000 (Thu Bay)
int Thu(DATE d) {
    DATE curdate = {1, 1, 2000};
    long kc = Khoangcach(d, curdate);
    int du = static_cast<int>(kc % 7);
    if (du < 0) du += 7;
    return du;
}

// Chuyen ma thu sang ten goi (khong cap phat dong)
std::string_view Dich(int t) {
    switch (t) {
        case 0: return "thu bay";
        case 1: return "chu nhat";
        case 2: return "thu hai";
        case 3: return "thu ba";
        case 4: return "thu tu";
        case 5: return "thu nam";
        case 6: return "thu sau";
        default: return "khong hop le";
    }
}

int main() {
    DATE d{2, 1, 2000};
    std::cout << "Ngay " << d.ngay << "/" << d.thang << "/" << d.nam 
              << " la " << Dich(Thu(d)) << "\n";
    return 0;
}

#include <iostream>
#include <string>

struct Ngaythang {
    int ng;
    int th;
    int nam;
};

struct Sinhvien {
    std::string hoten;
    Ngaythang ns;
    int gt; // 1: Nam, 0: Nu
    float diem;
};

// 1. Truyen bang gia tri (copy)
void in(Sinhvien x) {
    std::cout << x.hoten << "\t"
              << x.ns.ng << "/" << x.ns.th << "/" << x.ns.nam << "\t"
              << (x.gt ? "Nam" : "Nu") << "\t"
              << x.diem << "\n";
}

// 2. Truyen bang con tro (pointer)
void capNhatDiem(Sinhvien *p, float diemMoi) {
    if (p != nullptr) {
        p->diem = diemMoi;
    }
}

// 3. Truyen bang tham chieu (reference)
void suaTen(Sinhvien &r, const std::string &tenMoi) {
    r.hoten = tenMoi;
}

// 4. Truyen mang qua con tro hang (const pointer - read-only)
void inds(const Sinhvien *a, int n) {
    for (int i = 0; i < n; ++i) {
        in(a[i]);
    }
}

int main() {
    Sinhvien lop[2] = {
        {"Nguyen Van A", {15, 5, 2002}, 1, 8.0f},
        {"Tran Thi B",   {20, 8, 2003}, 0, 7.5f}
    };

    capNhatDiem(&lop[0], 9.0f);
    suaTen(lop[1], "Tran Thi Bich");

    inds(lop, 2);
    return 0;
}
